function checkArtifactDomains(file, value) {
    const table = exports.DOMAIN_TABLES[file];
    const undeclared = new Set();
    const violations = [];
    let checked = 0;
    const walk = (v, p) => {
        if (Array.isArray(v)) {
            v.forEach((x) => walk(x, `${p}[*]`));
            return;
        }
        if (v && typeof v === 'object') {
            for (const [k, x] of Object.entries(v))
                walk(x, p ? `${p}.${k}` : k);
            return;
        }
        if (typeof v !== 'number')
            return;
        checked++;
        const d = table?.[p];
        if (!d) {
            undeclared.add(p);
            return;
        }
        if (!d.ok(v))
            violations.push(`${p} = ${v} is not ${d.label}`);
    };
    walk(value, '');
    if (!table)
        return { checked, undeclared: ['<no domain table for this artifact>'], violations };
    return { checked, undeclared: [...undeclared], violations };
}
